application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root { --ink: #182331; --muted: #718096; --line: #e4eaf1; --blue: #3667e8; --blue-soft: #eef3ff; --mint: #dff7eb; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; color: var(--ink); background: linear-gradient(135deg, #f5f8ff 0%, #fbfcfe 55%, #effaf7 100%); font-family: 'DM Sans', sans-serif; }
.page-shell { width: min(920px, calc(100% - 32px)); margin: 0 auto; padding: 52px 0 28px; }
.quiz-card { background: rgba(255,255,255,.92); border: 1px solid rgba(218,226,239,.9); border-radius: 24px; box-shadow: 0 20px 55px rgba(33,55,95,.1); overflow: hidden; }
.quiz-header { padding: 42px 48px 34px; background: linear-gradient(115deg, #f0f4ff, #f9fbff); border-bottom: 1px solid var(--line); }
.eyebrow { color: var(--blue); font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
h1 { margin: 10px 0 8px; font: 700 clamp(30px, 5vw, 44px)/1.1 'Space Grotesk', sans-serif; letter-spacing: -.04em; }
.quiz-header p { margin: 0; color: var(--muted); font-size: 16px; }
.questions { padding: 8px 48px 22px; }
.question { margin: 0; padding: 26px 0 30px; border: 0; border-bottom: 1px solid var(--line); }
.question:last-child { border-bottom: 0; }
legend { width: 100%; padding: 0; font-size: 17px; font-weight: 700; }
.question-number { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 32px; margin-right: 10px; color: var(--blue); background: var(--blue-soft); border-radius: 10px; font-size: 12px; vertical-align: middle; }
.options { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin: 20px 0 0 43px; }
.option { display: flex; align-items: center; gap: 10px; min-height: 48px; padding: 12px 14px; border: 1px solid var(--line); border-radius: 11px; color: #4b5a6d; cursor: pointer; transition: .2s ease; }
.option:hover { border-color: #aebff2; background: #fafbff; }
.option:has(input:checked) { border-color: var(--blue); color: var(--blue); background: var(--blue-soft); box-shadow: 0 3px 10px rgba(54,103,232,.1); }
.option input { position: absolute; opacity: 0; pointer-events: none; }
.radio-mark { width: 17px; height: 17px; flex: 0 0 17px; border: 2px solid #c5cfdd; border-radius: 50%; }
.option:has(input:checked) .radio-mark { border: 5px solid var(--blue); }
.quiz-footer { display: flex; align-items: center; gap: 18px; padding: 25px 48px 30px; background: #fbfcfe; border-top: 1px solid var(--line); }
button { border: 0; border-radius: 11px; padding: 14px 20px; color: white; background: var(--blue); font: 700 14px 'DM Sans', sans-serif; cursor: pointer; box-shadow: 0 7px 16px rgba(54,103,232,.22); transition: .2s; }
button:hover { background: #2856d1; transform: translateY(-1px); } button span { margin-left: 8px; font-size: 18px; }
.status { flex: 1; margin: 0; color: #c14d54; font-size: 13px; }
.score-panel { display: flex; align-items: baseline; gap: 5px; padding-left: 18px; border-left: 1px solid var(--line); white-space: nowrap; }
.score-label { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .08em; font-weight: 700; }
.score-panel strong { color: var(--blue); font: 700 30px 'Space Grotesk', sans-serif; }
.score-total { color: var(--muted); font-size: 14px; }
.page-note { color: #8290a2; text-align: center; font-size: 12px; }
@media (max-width: 680px) { .page-shell { padding-top: 20px; } .quiz-header, .questions { padding-left: 24px; padding-right: 24px; } .quiz-footer { flex-wrap: wrap; padding: 22px 24px 25px; } .options { grid-template-columns: 1fr; margin-left: 0; } .status { order: 3; flex-basis: 100%; } .score-panel { margin-left: auto; } }

application.javascript:
const form = document.getElementById('quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const statusElement = document.getElementById('status');
const correctAnswers = ['Mars', 'Pacific Ocean', 'Carbon dioxide'];

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const answers = correctAnswers.map((_, index) => {
    const selected = form.querySelector(`input[name="question-${index + 1}"]:checked`);
    return selected ? selected.value : null;
  });

  if (answers.some((answer) => answer === null)) {
    statusElement.textContent = 'Please choose one answer for each question.';
    return;
  }

  const score = answers.reduce((total, answer, index) => total + (answer === correctAnswers[index] ? 1 : 0), 0);
  scoreElement.textContent = String(score);
  scoreElement.dataset.score = String(score);
  statusElement.textContent = score === 3 ? 'Perfect score!' : 'Quiz submitted. Nice work!';
});
